<?= view('layouts/app_header', ['user' => $user, 'activePage' => $activePage, 'title' => $title]) ?>
<?php
$canRestoreTrash = \App\Libraries\RolePolicy::allows($user ?? [], 'files.manage');
$canPermanentDeleteTrash = \App\Libraries\RolePolicy::allows($user ?? [], 'files.delete_permanently');
$canManageTrash = $canRestoreTrash || $canPermanentDeleteTrash;
$imageTypes = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'];
$videoTypes = ['mp4', 'mov', 'webm'];
$folders = $folders ?? [];
$serverItems = $serverItems ?? [];
$visibleItems = array_merge($folders, $files, $serverItems);
$totalBytes = array_sum(array_map(static fn (array $item): int => (int) $item['size'], $visibleItems));
$expiringSoon = count(array_filter($visibleItems, static fn (array $item): bool => isset($item['trash_days_remaining']) && (int) $item['trash_days_remaining'] <= 7));
$pagination = $pagination ?? ['current_page' => 1, 'total_pages' => 1, 'total_results' => count($visibleItems)];
$trashPageUrl = static function (int $page) use ($query, $type): string {
    $parameters = array_filter(['q' => $query, 'type' => $type, 'page' => $page > 1 ? $page : null], static fn ($value): bool => $value !== null && $value !== '');
    return site_url('workspace/trash') . ($parameters === [] ? '' : '?' . http_build_query($parameters));
};
?>
