        <div class="card trash-card">
            <form class="trash-filter" method="get" data-ajax-live-search><div class="row g-2 align-items-center"><div class="col-lg-7"><label class="visually-hidden" for="trashSearch">Search Trash</label><div class="input-group"><span class="input-group-text"><i class="bi bi-search"></i></span><input class="form-control" id="trashSearch" data-search-suggestions="<?= esc(site_url('workspace/search-suggestions/trash')) ?>" name="q" value="<?= esc($query) ?>" placeholder="Search name, original location, deletion reason, or user"></div></div><div class="col-sm-7 col-lg-3"><label class="visually-hidden" for="trashType">File type</label><select class="form-select" id="trashType" name="type"><option value="">All file types</option><?php foreach ($fileTypes as $fileType): ?><option value="<?= esc((string) $fileType['filetype']) ?>" <?= $type === $fileType['filetype'] ? 'selected' : '' ?>><?= esc(strtoupper((string) $fileType['filetype'])) ?></option><?php endforeach; ?></select></div><div class="col-sm-5 col-lg-2 d-grid"><button class="btn btn-primary" type="submit"><i class="bi bi-funnel me-1"></i>Filter</button></div></div><?php if ($query !== '' || $type !== ''): ?><div class="mt-2"><a class="small text-decoration-none" href="<?= esc(site_url('workspace/trash')) ?>"><i class="bi bi-x-circle me-1"></i>Clear filters</a></div><?php endif; ?></form>

