                    <article class="trash-item trash-folder-item" data-trash-item>
                        <?php if ($canManageTrash): ?><label class="trash-select-wrap" title="Select folder <?= esc($folder['name']) ?>"><input class="form-check-input trash-select" type="checkbox" data-trash-select data-trash-type="folder" data-trash-id="<?= (int) $folder['id'] ?>" aria-label="Select folder <?= esc($folder['name']) ?>"></label><?php endif; ?>
                        <a class="trash-preview trash-folder-preview" href="<?= esc(site_url('workspace/trash/folders/' . (int) $folder['id'])) ?>" aria-label="Open deleted folder <?= esc($folder['name']) ?>"><i class="bi bi-folder-fill"></i></a><span class="trash-type">Folder</span>
                        <div class="trash-content"><div class="trash-name"><?= esc($folder['name']) ?></div><div class="trash-meta"><?= $fileCount ?> file<?= $fileCount === 1 ? '' : 's' ?><?php if ($subfolderCount > 0): ?> &middot; <?= $subfolderCount ?> subfolder<?= $subfolderCount === 1 ? '' : 's' ?><?php endif; ?></div><div class="trash-meta"><?= esc(format_bytes((int) $folder['size'])) ?> &middot; Deleted by <?= esc($folder['deleted_by_name'] ?: 'Unknown') ?></div><div class="trash-meta"><?= esc(! empty($folder['deleted_at']) ? \App\Libraries\DisplayTime::format($folder['deleted_at'], 'M d, Y g:i A') : 'Deletion date unavailable') ?></div><div class="retention-row"><strong><?= $days ?> day<?= $days === 1 ? '' : 's' ?> remaining</strong><span><?= esc(\App\Libraries\DisplayTime::format($folder['trash_expires_at'])) . ' PHT' ?></span></div><div class="retention-progress"><div class="h-100 <?= esc($barClass) ?>" style="width: <?= $percentage ?>%"></div></div><div class="trash-reason"><i class="bi bi-folder2 me-1"></i><?= esc($folder['reason'] ?: 'Folder moved to Trash.') ?></div></div>
