                <?php foreach ($files as $file): ?><?php $filetype = strtolower((string) $file['filetype']); $kind = in_array($filetype, $imageTypes, true) ? 'image' : (in_array($filetype, $videoTypes, true) ? 'video' : 'file'); $previewUrl = site_url('workspace/trash/' . (int) $file['id'] . '/preview'); $days = (int) $file['trash_days_remaining']; $percentage = max(0, min(100, (int) round(($days / max(1, $retentionDays)) * 100))); $barClass = $days <= 7 ? 'bg-danger' : ($days <= 14 ? 'bg-warning' : 'bg-primary'); $mediaTitle = \App\Libraries\MediaTitle::forFile($file); ?>
                    <article class="trash-item" data-trash-item>
                        <?php if ($canManageTrash): ?><label class="trash-select-wrap" title="Select <?= esc($mediaTitle) ?>"><input class="form-check-input trash-select" type="checkbox" data-trash-select data-trash-type="file" data-trash-id="<?= (int) $file['id'] ?>" aria-label="Select <?= esc($mediaTitle) ?>"></label><?php endif; ?>
                        <?php if ($kind !== 'file'): ?><button class="trash-preview" type="button" data-bs-toggle="modal" data-bs-target="#trashPreviewModal" data-trash-preview data-preview-kind="<?= esc($kind) ?>" data-preview-src="<?= esc($previewUrl) ?>" data-preview-name="<?= esc($mediaTitle, 'attr') ?>" aria-label="Preview <?= esc($mediaTitle) ?>"><?php if ($kind === 'image'): ?><img src="<?= esc($previewUrl) ?>" alt="Preview of <?= esc($mediaTitle) ?>" loading="lazy"><?php else: ?><i class="bi bi-play-circle-fill"></i><?php endif; ?></button><?php else: ?><div class="trash-preview"><i class="bi bi-file-earmark"></i></div><?php endif; ?><span class="trash-type"><?= esc($filetype ?: 'file') ?></span>
                        <div class="trash-content"><div class="trash-name" title="<?= esc($mediaTitle) ?>"><?= esc($mediaTitle) ?></div><div class="trash-meta"><?= esc(format_bytes((int) $file['size'])) ?> &middot; Deleted by <?= esc($file['deleted_by_name'] ?: 'Unknown') ?></div><div class="trash-meta"><?= esc(($file['deleted_at'] ?? $file['last_action_at']) ? \App\Libraries\DisplayTime::format($file['deleted_at'] ?? $file['last_action_at']) : 'Deletion date unavailable') ?></div><div class="retention-row"><strong><?= $days ?> day<?= $days === 1 ? '' : 's' ?> remaining</strong><span><?= esc(\App\Libraries\DisplayTime::format($file['trash_expires_at'])) . ' PHT' ?></span></div><div class="retention-progress"><div class="h-100 <?= esc($barClass) ?>" style="width: <?= $percentage ?>%"></div></div><div class="trash-reason"><i class="bi bi-info-circle me-1"></i><?= esc($file['reason'] ?: 'No deletion reason recorded.') ?></div></div>
