<div class="modal fade" id="trashPreviewModal" tabindex="-1" aria-labelledby="trashPreviewTitle" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title text-truncate" id="trashPreviewTitle">Trash preview</h5><div class="small text-muted">Preview only. The item remains in Trash until restored.</div></div><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body trash-preview-body"><img class="d-none" id="trashPreviewImage" src="" alt=""><video class="d-none" id="trashPreviewVideo" src="" controls preload="metadata"></video></div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-bs-dismiss="modal">Close</button></div></div></div></div>
<script>
document.addEventListener('DOMContentLoaded', function () {
    var previewModal = document.getElementById('trashPreviewModal'); var previewImage = document.getElementById('trashPreviewImage'); var previewVideo = document.getElementById('trashPreviewVideo');
    previewModal.addEventListener('show.bs.modal', function (event) { var trigger = event.relatedTarget; var kind = trigger.dataset.previewKind; document.getElementById('trashPreviewTitle').textContent = trigger.dataset.previewName || 'Trash preview'; previewImage.classList.toggle('d-none', kind !== 'image'); previewVideo.classList.toggle('d-none', kind !== 'video'); if (kind === 'image') { previewImage.src = trigger.dataset.previewSrc; previewImage.alt = 'Preview of ' + (trigger.dataset.previewName || 'media'); } if (kind === 'video') { previewVideo.src = trigger.dataset.previewSrc; previewVideo.load(); } });
    previewModal.addEventListener('hidden.bs.modal', function () { previewImage.src = ''; previewVideo.pause(); previewVideo.removeAttribute('src'); previewVideo.load(); });

    var bulkForm = document.getElementById('trashBulkForm'); if (!bulkForm) return; var selectedTrashIds = new Set(); var selectionInputs = document.getElementById('trashSelectedInputs'); var selectionCount = document.getElementById('trashSelectionCount'); var selectionActions = document.getElementById('trashSelectionActions'); var selectAllButton = document.getElementById('selectAllTrash');
    var selectionKey = function (checkbox) { return checkbox.dataset.trashType + ':' + checkbox.dataset.trashId; };
    var getVisibleIds = function () { var ids = []; document.querySelectorAll('[data-trash-select]').forEach(function (checkbox) { var key = selectionKey(checkbox); if (ids.indexOf(key) === -1) ids.push(key); }); return ids; };
    var syncSelection = function () { document.querySelectorAll('[data-trash-select]').forEach(function (checkbox) { var selected = selectedTrashIds.has(selectionKey(checkbox)); checkbox.checked = selected; var item = checkbox.closest('[data-trash-item]'); if (item) item.classList.toggle('is-selected', selected); }); selectionInputs.replaceChildren(); selectedTrashIds.forEach(function (key) { var parts = key.split(':'); var input = document.createElement('input'); input.type = 'hidden'; input.name = parts[0] === 'server' ? 'server_ids[]' : (parts[0] === 'folder' ? 'folder_ids[]' : 'file_ids[]'); input.value = parts[1]; selectionInputs.appendChild(input); }); var count = selectedTrashIds.size; var visibleIds = getVisibleIds(); var allVisibleSelected = visibleIds.length > 0 && visibleIds.every(function (id) { return selectedTrashIds.has(id); }); selectionCount.textContent = count + ' selected'; selectionCount.classList.toggle('d-none', count === 0); selectAllButton.innerHTML = '<i class="bi bi-check2-square me-1"></i>' + (allVisibleSelected ? 'Unselect all' : 'Select all visible'); selectionActions.hidden = count === 0; document.querySelectorAll('[data-trash-bulk-action]').forEach(function (button) { button.disabled = count === 0; }); };
    document.querySelectorAll('[data-trash-select]').forEach(function (checkbox) { checkbox.addEventListener('change', function () { var key = selectionKey(checkbox); if (checkbox.checked) selectedTrashIds.add(key); else selectedTrashIds.delete(key); syncSelection(); }); });
    selectAllButton.addEventListener('click', function () { var visibleIds = getVisibleIds(); var shouldSelect = !visibleIds.every(function (id) { return selectedTrashIds.has(id); }); visibleIds.forEach(function (id) { if (shouldSelect) selectedTrashIds.add(id); else selectedTrashIds.delete(id); }); syncSelection(); });
    bulkForm.addEventListener('submit', function (event) { if (selectedTrashIds.size === 0) { event.preventDefault(); return; } }); syncSelection();
});
</script>
